# S4 signature inspection is opt-in, exact, non-executing and fail-closed.
source('skills/_shared/scripts/calls_check.R')
n<-0L;check<-function(ok,label){stopifnot(isTRUE(ok));n<<-n+1L;cat('PASS',label,'\n')};refuse<-function(expr,label){x<-tryCatch({force(expr);NULL},error=identity);check(inherits(x,'error'),label)}
e<-new.env(parent=globalenv());methods::setGeneric('omicstatS4DefaultFixture',function(x,...)methods::standardGeneric('omicstatS4DefaultFixture'),where=e)
methods::setMethod('omicstatS4DefaultFixture','ANY',function(x,alpha=3,weights=c(1,2),verbose=FALSE)stop('The method body must never execute'),where=e)
g<-methods::getGeneric('omicstatS4DefaultFixture',where=e);fm<-.os_s4_method_formals(g,list(x='ANY'))
check(identical(names(fm),c('x','alpha','weights','verbose')),'full S4 .local formals extracted without execution')
check(identical(paste(deparse(fm[['x']]),collapse=''),''),'required formal stays required')
check(identical(fm$alpha,3)&&identical(fm$verbose,FALSE),'scalar defaults retained')
check(identical(paste(deparse(fm$weights),collapse=''),'c(1, 2)'),'unevaluated expression default retained')
refuse(.os_s4_method_formals(g,list(x='matrix')),'no inherited ANY fallback for undeclared exact method')
refuse(.os_s4_method_formals(g,list(y='ANY')),'wrong signature argument refused')
refuse(.os_s4_method_formals(g,list(x='')),'empty signature refused')
refuse(.os_s4_method_formals(g,'ANY'),'unnamed signature refused')
refuse(.os_s4_method_formals(stats::lm,list(x='ANY')),'non-S4 function refused')
f<-function(x,alpha=2)stop('No body execution');check(identical(.os_expanded_method_formals(f),formals(f)),'direct expanded formals retained')
f<-function(x,...){.local<-function(x,alpha=2)stop('No body execution');.local(x,...)};check(identical(.os_expanded_method_formals(f)$alpha,2),'canonical wrapper accepted')
f<-function(x,...){x<-42;.local<-function(x,alpha=2)x;.local(x,...)};refuse(.os_expanded_method_formals(f),'extra executable wrapper statement refused')
f<-function(x,...){.local<-function(x,alpha=2)x;.local(x+1,...)};refuse(.os_expanded_method_formals(f),'transformed forwarding refused')
f<-function(x,...){other<-function(x,alpha=2)x;other(x,...)};refuse(.os_expanded_method_formals(f),'noncanonical closure name refused')
check(check_default_drift(list(calls=list(list(fn='stats::prcomp',args=list(center=list(function_default='TRUE'))))))$ok,'existing S3 defaults unchanged')
check(!check_default_drift(list(calls=list(list(fn='stats::prcomp',args=list(center=list(function_default='FALSE'))))))$ok,'existing S3 mismatch still rejected')
cat('S4 DEFAULT TESTS',n,'PASSED\n')
